import java.util.Scanner;

public class Main {
    static long powerMod(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int P = sc.nextInt();
        int K = sc.nextInt();
        final long MOD = 1000000007;

        if (K == 0) {
            System.out.println(powerMod(P, P - 1, MOD));
            return;
        }
        if (K == 1) {
            System.out.println(powerMod(P, P, MOD));
            return;
        }

        boolean[] visited = new boolean[P];
        int cycleLength = 0;
        int p = 1;
        while (!visited[p]) {
            visited[p] = true;
            cycleLength++;
            p = (int)((long)K * p % P);
        }

        System.out.println(powerMod(P, cycleLength, MOD));
    }
}
